// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceNativePocketCallbacks {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceNativePocketCallbacks = UniffiVTableCallbackInterfaceNativePocketCallbacks(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeNativePocketCallbacks.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface NativePocketCallbacks: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeNativePocketCallbacks.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface NativePocketCallbacks: handle missing in uniffiClone")
            }
        },
        listCards: { (
            uniffiHandle: UInt64,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> [PocketCard] in
                guard let uniffiObj = try? FfiConverterTypeNativePocketCallbacks.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.listCards(
                )
            }


            let writeReturn = { uniffiOutReturn.pointee = FfiConverterSequenceTypePocketCard.lower($0) }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypeHostRejection_lower
            )
        },
        removeCard: { (
            uniffiHandle: UInt64,
            cardId: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> NativePocketRemoval in
                guard let uniffiObj = try? FfiConverterTypeNativePocketCallbacks.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.removeCard(
                     cardId: try FfiConverterString.lift(cardId)
                )
            }


            let writeReturn = { uniffiOutReturn.pointee = FfiConverterTypeNativePocketRemoval_lower($0) }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypeHostRejection_lower
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceNativePocketCallbacks> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceNativePocketCallbacks>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitNativePocketCallbacks() {
    uniffi_truapi_server_fn_init_callback_vtable_nativepocketcallbacks(UniffiCallbackInterfaceNativePocketCallbacks.vtablePtr)
}

