    return try!  FfiConverterBool.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_truapi_server_fn_func_has_trusted_remote_permissions(
        FfiConverterString.lower(productId),uniffiCallStatus
    )
})
}
